# Generates ffmpeg-playground/src/yuv2rgb.rs.
import re, sys
ex = [l.split("\t")[1].strip() for l in open(sys.argv[1]) if "yuv2rgb_neon" in l.split("\t")[0]]
out = ['''//! libswscale/aarch64/yuv2rgb_neon.S, as swscale_unscaled.c calls it: only
//! for widths that are a multiple of 16 and even heights. src[] and
//! srcStride[] are the slice's plane pointers and strides; the table holds
//! the four chroma coefficients. Generated by gen/yuv2rgb.py.
use bums_macros as bums;
''']
bpp = {"argb": 4, "rgba": 4, "abgr": 4, "bgra": 4, "rgb24": 3, "bgr24": 3}
for name in ex:
    m = re.match(r"ff_(nv12|nv21|yuv420p|yuv422p|yuva420p)_to_(\w+)_neon$", name)
    ifmt, ofmt = m.group(1), m.group(2)
    b = bpp.get(ofmt, 2)
    crow = "h" if ifmt == "yuv422p" else "h / 2"
    planes = [("y", "ys", "(h - 1) * ys + w", "ys >= w")]
    if ifmt in ("nv12", "nv21"):
        planes.append(("uv", "uvs", f"({crow} - 1) * uvs + w", "uvs >= w"))
    else:
        planes += [("u", "us", f"({crow} - 1) * us + w / 2", "us >= w / 2"), ("v", "vs", f"({crow} - 1) * vs + w / 2", "vs >= w / 2")]
    if ifmt == "yuva420p":
        planes.append(("a", "as_", "(h - 1) * as_ + w", "as_ >= w"))
    pre = ["w % 16 == 0", "w >= 16", "w <= 8192", "h % 2 == 0", "h >= 2", "h <= 8192", "table.len() == 4",
           "src.len() == 4", "src_stride.len() == 4"]
    for i, (p, s, length, smin) in enumerate(planes):
        pre += [f"src[{i}] == {p}.as_ptr()", f"src_stride[{i}] == {s} as i32", f"{p}.len() == {length}", smin, f"{s} <= 1073741824"]
    extra_sig = "".join(f", {p}: &[u8], {s}: usize" for p, s, _, _ in planes)
    if ofmt == "gbrp":
        outs = [("dst0", "ls0"), ("dst1", "ls1"), ("dst2", "ls2")]
        for d, l in outs:
            pre += [f"{d}.len() == (h - 1) * {l} + w", f"{l} >= w", f"{l} <= 1073741824"]
        dargs = [x for d, l in outs for x in (f"{d}.as_mut_ptr()", l)]
        dsig = "".join(f", {d}: &mut [u8], {l}: usize" for d, l in outs)
    else:
        pre += [f"dst.len() == (h - 1) * linesize + {b} * w", f"linesize >= {b} * w", "linesize <= 1073741824"]
        dargs = ["dst.as_mut_ptr()", "linesize"]
        dsig = ", dst: &mut [u8], linesize: usize"
    out.append(f'''#[bums::check_mem_safe("yuv2rgb_neon.S", w, h, y_offset, y_coeff, table.as_ptr(), src.as_ptr(), src_stride.as_ptr(), {", ".join(dargs)},
    [{", ".join(pre)}])]
fn {name}(w: usize, h: usize, y_offset: i32, y_coeff: i32, table: &[i16], src: &[usize], src_stride: &[i32]{dsig}{extra_sig});
''')
print("\n".join(out))
